  const ACHIEVEMENT_RESET_VERSION = 3;
  function fresh(){return {version:ACHIEVEMENT_RESET_VERSION,syncedUid:null,level:1,xpTenthsIntoLevel:0,lifetimeXpTenthsAwarded:0,unlocked:{},ownedRewards:{},equipped:{},resolvedLevels:{},events:{},daysPlayed:[],currentStreak:0,bestCorrectStreak:0,baseline:null,updatedAt:Date.now()};}
  function canonicalRewardSlot(reward){return reward.gameId?`${reward.gameId}:${reward.slot||reward.type}`:reward.slot||reward.type;}
  function canonicalizeEquipped(equipped){const clean={};Object.values(equipped||{}).forEach(id=>{const reward=REWARDS.find(r=>r.id===id);if(reward)clean[canonicalRewardSlot(reward)]=id;});return clean;}
  function migrate(raw){if(!raw||Number(raw.version)<ACHIEVEMENT_RESET_VERSION)return fresh();const next=Object.assign(fresh(),raw);next.equipped=canonicalizeEquipped(next.equipped);return next;}
  function load(){try{return migrate(JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}'));}catch(_){return fresh();}}
  let state=load(), uid=null, syncing=false, cloudSaveTimer=null, cloudSaveQueued=false;
  let enabledGameIds=[...GAME_IDS];
  function save(){state.updatedAt=Date.now();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(_){}; scheduleCloud(); dispatchEvent(new CustomEvent('arcade-progression-changed',{detail:getSummary()}));}
  function scheduleCloud(){if(UNLOCK_ALL_REWARDS_FOR_TESTING||!uid||!global.FirebaseManager?.updateUserProfile)return;cloudSaveQueued=true;if(cloudSaveTimer)clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(flushCloudSave,250);}
  async function flushCloudSave(){cloudSaveTimer=null;if(syncing||!cloudSaveQueued)return;cloudSaveQueued=false;syncing=true;const snapshot=JSON.parse(JSON.stringify(state));await global.FirebaseManager.updateUserProfile(uid,{achievementSystem:snapshot});syncing=false;if(cloudSaveQueued)scheduleCloud();}
